<?php include 'config.php'; admin_only(); $message='';$type=''; if(isset($_POST['return'])){$id=$_POST['book_id'];$find=mysqli_prepare($conn,'SELECT book_id FROM issue_book WHERE book_id=? AND return_date IS NULL LIMIT 1');mysqli_stmt_bind_param($find,'s',$id);mysqli_stmt_execute($find);if(!mysqli_num_rows(mysqli_stmt_get_result($find))){$message='No active loan was found for that book.';$type='error';}else{$q=mysqli_prepare($conn,'UPDATE issue_book SET return_date=CURDATE() WHERE book_id=? AND return_date IS NULL');mysqli_stmt_bind_param($q,'s',$id);mysqli_stmt_execute($q);$q=mysqli_prepare($conn,"UPDATE books SET status='Available' WHERE book_id=?");mysqli_stmt_bind_param($q,'s',$id);mysqli_stmt_execute($q);$message='Return recorded and book marked available.';$type='success';}} $loans=mysqli_query($conn,"SELECT i.book_id,i.student_name,b.book_name FROM issue_book i LEFT JOIN books b ON b.book_id=i.book_id WHERE i.return_date IS NULL ORDER BY i.issue_date"); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receive return | LibraryHub</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><div class="app-shell"><main class="form-page"><section class="form-card"><a class="btn secondary" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Dashboard</a><p class="eyebrow" style="margin-top:25px">Circulation desk</p><h1>Receive a return</h1><p>Close an active loan and return the title to the shelf.</p><?php if($message): ?><div class="notice <?php echo $type; ?>"><?php echo e($message); ?></div><?php endif; ?><form method="post"><label>Active loan</label><select name="book_id" required><option value="">Select returned book</option><?php while($loan=mysqli_fetch_assoc($loans)): ?><option value="<?php echo e($loan['book_id']); ?>">#<?php echo e($loan['book_id']); ?> — <?php echo e($loan['book_name']); ?> (<?php echo e($loan['student_name']); ?>)</option><?php endwhile; ?></select><div class="form-actions"><button class="btn" name="return"><i class="fa-solid fa-check"></i> Confirm return</button><a class="btn secondary" href="issuedbooks.php">Loan history</a></div></form></section></main></div></body></html>
